final class Circle { // final class: cannot be extended by anyone
    private final double radius; // final field: can only be assigned once, in the constructor

    Circle(double radius) {
        this.radius = radius; // this is the ONE and ONLY assignment ever allowed
    }

    public final double area() { // final method: no subclass could ever override this
        return Math.PI * radius * radius;
    }
}

public class Main {
    public static void main(String[] args) {
        Circle circle = new Circle(5);
        System.out.println("Area: " + circle.area());

        // circle.radius = 10;                 // would NOT compile: radius is final, already set
        // class BigCircle extends Circle {}   // would NOT compile: Circle is a final class
    }
}

