import math
from typing import Final


# Python has no real enforcement for "final class" or "final field" built into the language
class Circle:
    def __init__(self, radius):
        self.radius: Final[float] = radius  # a type-checker hint only, NOT enforced at runtime

    def area(self):
        return math.pi * self.radius * self.radius


if __name__ == "__main__":
    circle = Circle(5)
    print("Area:", circle.area())

    # circle.radius = 10  # this actually WORKS at runtime in Python, Final is a static-analysis hint only

